package net.officefloor.hq.app.crew;

import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.pool.PoolRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** A name already on the sheet's crews or pools (a crew being a pool too), or a lead not on the sheet, is refused. */
public class SaveCrew {
    public void save(@Val CrewInput input, @Val Sheet sheet, CrewRepository crews, PoolRepository pools, PersonRepository people,
            Out<Crew> crewOut) throws InvalidCrewException {
        if (crews.find(sheet.id(), input.name()) != null) {
            throw new InvalidCrewException(input.name() + " is already a crew");
        }
        if (pools.find(sheet.id(), input.name()) != null) {
            throw new InvalidCrewException(input.name() + " is already a pool");
        }
        Person lead = people.find(sheet.id(), input.leadId());
        if (lead == null) throw new InvalidCrewException("No such person to lead the crew");
        crewOut.set(crews.save(sheet.id(), input.name(), lead.getId()));
    }
}
# Add a crew with a lead to the sheet. A blank name, one already on the sheet, or a lead not on the
# sheet, is refused (a 400) and writes nothing.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: validate
validate:
  class: net.officefloor.hq.app.crew.ValidateCrew
  next: load
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.crew.SaveCrew
  govern: [ transaction ]
  next: audit
# Last before the response: every rule has passed and the change is saved.
audit:
  class: net.officefloor.hq.app.crew.AuditCrewAdded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.crew.RespondWithCrew
  govern: [ transaction ]
# Add a pool to the sheet. A blank name, or one already on the sheet, is refused (a 400) and writes nothing.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: validate
validate:
  class: net.officefloor.hq.app.pool.ValidatePool
  next: load
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.pool.SavePool
  govern: [ transaction ]
  next: audit
# Last before the response: every rule has passed and the change is saved.
audit:
  class: net.officefloor.hq.app.pool.AuditPoolAdded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.pool.RespondWithPool
  govern: [ transaction ]

